//
//  SuggestionModels.swift
//  Clicky
//
//  Data model for proactive suggestions and the routines that feed them.
//  Suggestions are cards generated by ProactiveEngine (morning batch after
//  6 am while active) and announced via a ReplySource.scheduled chat entry.
//

import Foundation

/// One proactive suggestion card: shows in Home → Suggestions, counts into
/// the notch badge until read, and is never more than one batch a day.
struct LazySuggestion: Identifiable, Codable, Equatable {
    enum Kind: String, Codable {
        /// An overdue routine the user should settle.
        case routine
        /// Yesterday's most-used app — a factual mirror, not a nudge-loop.
        case usage
        /// Housekeeping notes (e.g. the ignore-breaks pause ending).
        case note
    }

    let id: UUID
    var kind: Kind
    var title: String
    var body: String
    /// Set for routine cards — lets the card's "Done" action reset the routine.
    var routineID: UUID?
    var createdAt: Date
    var isRead: Bool

    init(
        id: UUID = UUID(),
        kind: Kind,
        title: String,
        body: String,
        routineID: UUID? = nil,
        createdAt: Date = Date(),
        isRead: Bool = false
    ) {
        self.id = id
        self.kind = kind
        self.title = title
        self.body = body
        self.routineID = routineID
        self.createdAt = createdAt
        self.isRead = isRead
    }
}

/// A user-defined routine with a cadence. The engine nudges once a day when
/// one is past due ("settle overdue routines" — one calm card, never a loop).
struct LazyRoutine: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    /// Hours between runs (24 = daily, 72 = every three days, ...).
    var intervalHours: Double
    var lastRunDate: Date

    init(id: UUID = UUID(), name: String, intervalHours: Double, lastRunDate: Date = Date()) {
        self.id = id
        self.name = name
        self.intervalHours = intervalHours
        self.lastRunDate = lastRunDate
    }

    func nextDueDate() -> Date {
        lastRunDate.addingTimeInterval(intervalHours * 3600)
    }

    func isOverdue(asOf date: Date = Date()) -> Bool {
        date >= nextDueDate()
    }

    /// "3h ago" / "yesterday" / "2d ago" style label for the card body.
    func overdueLabel(asOf date: Date = Date()) -> String {
        let seconds = date.timeIntervalSince(nextDueDate())
        if seconds < 3600 {
            let minutes = max(1, Int(seconds / 60))
            return "\(minutes)m ago"
        }
        if seconds < 86_400 {
            let hours = Int(seconds / 3600)
            return "\(hours)h ago"
        }
        let days = Int(seconds / 86_400)
        return days == 1 ? "yesterday" : "\(days)d ago"
    }
}
